const baseline = $input.first().json.measure;
const schedule = $('Get Due Schedules1').first().json;

// Tracking object for performance monitoring
const tracking = {
  user_id: schedule.user_id,
  interval_days: schedule.interval_days || 7,
  processed_at: new Date().toISOString(),
  status: 'calculated'
};

if (!baseline) {
  return [{ json: { ...tracking, status: 'skipped', reason: 'No sensor data' } }];
}

const minVal = Math.round(baseline * (1+0.01*$('Get Due Schedules1').first().json.trigger_percentage));
const maxVal = minVal + 20;

return [{
  json: {
    ...tracking,
    minValue: minVal,
    maxValue: maxVal,
    type: $('Get Due Schedules1').first().json.usecase_name,
    user_id: $('Get Due Schedules1').first().json.user_id,
    active: true
  }
}];

const result = $input.first().json;
const parsed = $('extract and validate parameters1').first().json;

if (!result || !result.user_id) {
  return [{
    json: {
      statusCode: 404,
      ok: false,
      error: "Could not assign monitoring type. User, use case, or active mapping was not found.",
      userId: parsed.userId,
      monitoringType: parsed.monitoringType
    }
  }];
}

return [{
  json: {
    statusCode: 200,
    ok: true,
    message: "Monitoring type assigned successfully",
    userId: result.user_id,
    monitoringType: parsed.monitoringType,
    mappingId: result.feedback_config_rule_id,
    feedbackConfigRuleId: result.feedback_config_rule_id
  }
}];

const body = $input.first().json.body || {};

const userId = Number(body.userId ?? body.userid ?? body.UserID);
const monitoringType = String(
  body.monitoringType ?? body.monitoringtype ?? body.usecaseName ?? body.type ?? ""
).trim();

if (!Number.isFinite(userId) || userId <= 0) {
  return [{
    json: {
      statusCode: 400,
      ok: false,
      error: "Missing or invalid userId"
    }
  }];
}

if (!monitoringType) {
  return [{
    json: {
      statusCode: 400,
      ok: false,
      error: "Missing or invalid monitoringType"
    }
  }];
}

return [{
  json: {
    statusCode: 200,
    ok: true,
    userId,
    monitoringType
  }
}];

const req = $input.first().json;

const userIdRaw =
  req.query?.userId ??
  req.query?.userid ??
  req.body?.userId ??
  req.body?.userid;

const userId = Number(userIdRaw);

if (!Number.isInteger(userId) || userId <= 0) {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      error: "Missing or invalid userId. Use /monitoring-config?userId=100"
    }
  }];
}

return [{
  json: {
    valid: true,
    userId,
    params: [userId]
  }
}];

const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.id);

const userId = $('Fetch user monitoring mappings').first().json.userId;

const mappings = rows.map(m => ({
  id: m.id,
  mapping_id: m.mapping_id ?? m.id,
  feedback_config_rule_id: m.feedback_config_rule_id ?? m.id,
  usecase_id: m.usecase_id,
  type: m.type,
  usecase_name: m.usecase_name,
  usecase_description: m.usecase_description,
  active: m.active,

  minvalue: m.minvalue,
  maxvalue: m.maxvalue,
  minpulses: m.minpulses,
  maxpulses: m.maxpulses,
  minintensity: m.minintensity,
  maxintensity: m.maxintensity,
  minduration: m.minduration,
  maxduration: m.maxduration,
  mininterval: m.mininterval,
  maxinterval: m.maxinterval
}));

if (mappings.length === 0) {
  return [{
    json: {
      statusCode: 200,
      ok: true,
      source: "no_user_mappings",
      userId,
      mappings: [],
      usecase_mappings: [],
      fallbackRequired: true
    }
  }];
}

return [{
  json: {
    statusCode: 200,
    ok: true,
    source: "user_mappings",
    userId,
    mappings,
    usecase_mappings: mappings,
    fallbackRequired: false
  }
}];

