const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.id);

const userId = $('Fetch user monitoring mappings').first().json.userId;

if (!rows || rows.length === 0) {
  return [{
    json: {
      statusCode: 404,
      ok: false,
      source: "fallback_missing",
      userId,
      error: "No user mappings found and fallback mapping 9999 is missing"
    }
  }];
}

const m = rows[0];

const fallbackMapping = {
  id: m.id,
  mapping_id: m.mapping_id ?? m.id,
  feedback_config_rule_id: m.feedback_config_rule_id ?? m.id,
  usecase_id: m.usecase_id,
